//! Example 5: Synthetic cochlear demo (NOT the Spiking Heidelberg Digits dataset)
//!
//! Generates a synthetic 8-channel, 4-class spike stream and reports
//! **NeuroBench-style** metrics. Accuracy here says nothing about real speech data:
//! the classes are generated by this file and are easily separable.
//! - **Top-1 Accuracy** (on noisy acoustic samples)
//! - **SynOps per Inference (AC vs MAC)**
//! - **Sparsity Rate (%)**
//! - **Time-to-Decision (TTD)**
//!
//! Execution:
//! ```bash
//! cargo run -p snn_core_demos --example 05_synthetic_cochlea_demo
//! ```

#![allow(clippy::needless_range_loop)]

use snn_core::metrics::{LatencyTracker, SparsityMeter, SynOpsTracker};
use snn_core::traits::Readout;
use snn_core::{
    CompactLifPopulation, Fix32, GenericStaticNetwork, LifConfig, ResetMode, StaticCsrSynapses,
    StaticSpikeDelayLine, Synapse, TrainableReadoutLayer,
};

const COCHLEA_CHANNELS: usize = 8;
const RESERVOIR_SIZE: usize = 32;
const RESERVOIR_SIZE_P1: usize = RESERVOIR_SIZE + 1; // 33
const MAX_INTERNAL_SYNAPSES: usize = 256;
const MAX_INPUT_SYNAPSES: usize = 64;
const COCHLEA_CHANNELS_P1: usize = COCHLEA_CHANNELS + 1; // 9
const NUM_CLASSES: usize = 4; // 4 spatio-temporal acoustic patterns
const FEATURE_DIM: usize = RESERVOIR_SIZE + 1; // 33 (1 bias + 32 state traces)
const AUDIO_SAMPLE_TICKS: usize = 30; // 30 temporal ticks per audio sample

/// Generates an acoustic cochlear signal for a target class with random variation (noise/jitter).
fn generate_cochlea_sample(
    class: usize,
    rng: &mut fastrand::Rng,
) -> [[Fix32; COCHLEA_CHANNELS]; AUDIO_SAMPLE_TICKS] {
    let mut frames = [[Fix32::ZERO; COCHLEA_CHANNELS]; AUDIO_SAMPLE_TICKS];

    match class {
        0 => {
            // Class 0: Low-frequency formant (channels 0 and 1)
            let start = 5 + rng.usize(0..4);
            let end = (start + 12).min(AUDIO_SAMPLE_TICKS);
            for t in start..end {
                frames[t][0] = Fix32::from_num(1.8);
                frames[t][1] = Fix32::from_num(1.4);
            }
        }
        1 => {
            // Class 1: High-frequency formant (channels 6 and 7)
            let start = 5 + rng.usize(0..4);
            let end = (start + 12).min(AUDIO_SAMPLE_TICKS);
            for t in start..end {
                frames[t][6] = Fix32::from_num(1.5);
                frames[t][7] = Fix32::from_num(1.9);
            }
        }
        2 => {
            // Class 2: Ascending chirp (frequency rise: 1 -> 3 -> 5 -> 7)
            for (step, &ch) in [1, 3, 5, 7].iter().enumerate() {
                let t_start = 4 + step * 5;
                for t in t_start..(t_start + 4).min(AUDIO_SAMPLE_TICKS) {
                    frames[t][ch] = Fix32::from_num(2.0);
                }
            }
        }
        _ => {
            // Class 3: Descending chirp (frequency fall: 6 -> 4 -> 2 -> 0)
            for (step, &ch) in [6, 4, 2, 0].iter().enumerate() {
                let t_start = 4 + step * 5;
                for t in t_start..(t_start + 4).min(AUDIO_SAMPLE_TICKS) {
                    frames[t][ch] = Fix32::from_num(2.0);
                }
            }
        }
    }

    // Add slight background noise
    for t in 0..AUDIO_SAMPLE_TICKS {
        for ch in 0..COCHLEA_CHANNELS {
            if rng.f32() < 0.05 {
                frames[t][ch] += Fix32::from_num(0.2);
            }
        }
    }

    frames
}

fn main() {
    println!("=== 🎙️ snn_core: Bio-Acoustic Benchmark in SHD Style (NeuroBench) ===\n");

    // 1. Initialize compact population of 32 LIF neurons (Flash ROM)
    let config = LifConfig::new(
        Fix32::ONE,
        Fix32::from_bits(58982), // decay = 0.90
        Fix32::ZERO,
        1,
    )
    .with_reset_mode(ResetMode::Subtract);
    let neurons = CompactLifPopulation::<RESERVOIR_SIZE>::new(config);

    // 2. Tonotopic input synapses (frequency channels into reservoir)
    let mut input_synapses = Vec::new();
    let mut rng = fastrand::Rng::with_seed(101);
    for ch in 0..COCHLEA_CHANNELS {
        for target in (ch * 4)..((ch + 1) * 4) {
            input_synapses.push(Synapse::new(ch, target, Fix32::from_num(1.4)));
        }
    }

    // 3. Recurrent synapses following Dale's principle (80/20)
    let mut internal_synapses = Vec::new();
    for i in 0..RESERVOIR_SIZE {
        for j in 0..RESERVOIR_SIZE {
            if i != j && rng.f32() < 0.20 && internal_synapses.len() < MAX_INTERNAL_SYNAPSES {
                let is_inhibitory = rng.f32() < 0.20;
                let w = if is_inhibitory {
                    Fix32::from_num(-0.5)
                } else {
                    Fix32::from_num(0.4)
                };
                internal_synapses.push(Synapse::new(i, j, w));
            }
        }
    }

    let internal_csr = StaticCsrSynapses::<RESERVOIR_SIZE_P1, MAX_INTERNAL_SYNAPSES>::from_synapses(
        &internal_synapses,
    );
    let input_csr = StaticCsrSynapses::<COCHLEA_CHANNELS_P1, MAX_INPUT_SYNAPSES>::from_synapses(
        &input_synapses,
    );

    let mut network = GenericStaticNetwork::<_, _, _, RESERVOIR_SIZE, COCHLEA_CHANNELS>::new(
        neurons,
        internal_csr,
        input_csr,
    );

    // Supervised online trainable Readout layer (LMS / Delta Rule with L2 regularization)
    let mut readout = TrainableReadoutLayer::<NUM_CLASSES, FEATURE_DIM>::new(
        Fix32::from_num(0.02),   // Learning rate
        Fix32::from_num(0.0001), // L2 regularization
    );

    println!("1. Online training of Readout layer (180 acoustic presentations)...");
    let mut train_rng = fastrand::Rng::with_seed(42);
    for _ in 0..180 {
        let class = train_rng.usize(0..NUM_CLASSES);
        let sample = generate_cochlea_sample(class, &mut train_rng);

        let mut state_traces = [Fix32::ZERO; RESERVOIR_SIZE];
        let mut delay_line = StaticSpikeDelayLine::<COCHLEA_CHANNELS, 4>::new();
        network.reset();

        for t in 0..AUDIO_SAMPLE_TICKS {
            let mut cochlea_spikes = [false; COCHLEA_CHANNELS];
            for ch in 0..COCHLEA_CHANNELS {
                if sample[t][ch] >= Fix32::ONE {
                    cochlea_spikes[ch] = true;
                }
            }
            delay_line.push(&cochlea_spikes);
            let delayed_spikes = delay_line.get_delayed(1);

            let mut current_input = sample[t];
            for ch in 0..COCHLEA_CHANNELS {
                if delayed_spikes[ch] {
                    current_input[ch] += Fix32::from_num(0.3);
                }
            }

            let spikes = *network.tick(&current_input);
            for i in 0..RESERVOIR_SIZE {
                if spikes[i] {
                    state_traces[i] += Fix32::from_num(0.2);
                }
            }
        }

        readout.train_step(&state_traces, class);
    }
    println!("   -> Training completed successfully.\n");

    println!("2. Evaluating NeuroBench metrics (40 test trials with noise)...");
    let mut test_rng = fastrand::Rng::with_seed(999);
    let mut correct_predictions = 0;
    let total_tests = 40;

    let mut synops_tracker = SynOpsTracker::new();
    let mut sparsity_meter = SparsityMeter::new();
    let mut latency_tracker = LatencyTracker::new();

    for test_idx in 0..total_tests {
        let target_class = test_idx % NUM_CLASSES;
        let sample = generate_cochlea_sample(target_class, &mut test_rng);

        let mut state_traces = [Fix32::ZERO; RESERVOIR_SIZE];
        let mut delay_line = StaticSpikeDelayLine::<COCHLEA_CHANNELS, 4>::new();
        network.reset();

        for t in 0..AUDIO_SAMPLE_TICKS {
            // Temporal buffering of cochlear spikes (spatio-temporal alignment via delay line)
            let mut cochlea_spikes = [false; COCHLEA_CHANNELS];
            for ch in 0..COCHLEA_CHANNELS {
                if sample[t][ch] >= Fix32::ONE {
                    cochlea_spikes[ch] = true;
                }
            }
            delay_line.push(&cochlea_spikes);
            let delayed_spikes = delay_line.get_delayed(1);

            let mut current_input = sample[t];
            for ch in 0..COCHLEA_CHANNELS {
                if delayed_spikes[ch] {
                    current_input[ch] += Fix32::from_num(0.3);
                }
            }

            let spikes = *network.tick(&current_input);

            // Record AC SynOps
            for &spiker in &network.active_spikes_buf[..network.active_spikes_count] {
                let start = network.internal_synapses.row_ptrs[spiker as usize] as usize;
                let end = network.internal_synapses.row_ptrs[spiker as usize + 1] as usize;
                synops_tracker.record_synaptic_spikes(end.saturating_sub(start));
            }

            // Integrate spike activity
            for i in 0..RESERVOIR_SIZE {
                if spikes[i] {
                    state_traces[i] += Fix32::from_num(0.2);
                }
            }

            // Record sparsity
            sparsity_meter.record_tick(RESERVOIR_SIZE, network.active_spikes_count);

            // Track Time-to-Decision (TTD) according to official NeuroBench methodology:
            // Decision is locked as soon as confidence margin between top-1 and top-2 exceeds threshold.
            let mut best_score = Fix32::from_bits(i32::MIN);
            let mut second_score = Fix32::from_bits(i32::MIN);
            for c in 0..NUM_CLASSES {
                let mut score = readout.weights[c][0];
                for (i, &x) in state_traces.iter().enumerate() {
                    if i + 1 < FEATURE_DIM {
                        score += readout.weights[c][i + 1] * x;
                    }
                }
                if score > best_score {
                    second_score = best_score;
                    best_score = score;
                } else if score > second_score {
                    second_score = score;
                }
            }
            let confidence_margin = best_score.saturating_sub(second_score);
            let is_confident_decision = confidence_margin >= Fix32::from_num(0.35);

            latency_tracker.record_tick(t, network.active_spikes_count, is_confident_decision);
        }

        // Readout MACs: (NumClasses * NumFeatures)
        synops_tracker.record_dense_mac(NUM_CLASSES * FEATURE_DIM);
        let pred_class = Readout::predict(&readout, &state_traces);

        if pred_class == target_class {
            correct_predictions += 1;
        }
    }

    let top1_accuracy = (correct_predictions as f32 / total_tests as f32) * 100.0;
    let avg_synops_per_inference = synops_tracker.total_synops() / (total_tests as u64);

    println!("============================================================");
    println!("📊 BIO-ACOUSTIC BENCHMARK REPORT (NeuroBench Metrics)");
    println!("ℹ️  Dataset: Synthetic cochlear filterbank (8 channels, 4 classes)");
    println!("============================================================");
    println!(
        "• Top-1 Accuracy              : {:.1}% ({}/{} successful)",
        top1_accuracy, correct_predictions, total_tests
    );
    println!(
        "• Average SynOps / Inference  : {} ops",
        avg_synops_per_inference
    );
    println!(
        "  - Sparse AC Accumulations   : {} ops / inference",
        synops_tracker.accumulate_ops / (total_tests as u64)
    );
    println!(
        "  - Dense MACs (Readout)      : {} ops / inference",
        synops_tracker.multiply_accumulate_ops / (total_tests as u64)
    );
    println!(
        "• Sparsity Rate               : {:.1}% (Temporal inactivity)",
        sparsity_meter.sparsity_percent()
    );
    println!(
        "• Latency to First Spike      : tick #{}",
        latency_tracker.first_spike_tick.unwrap_or(0)
    );
    println!(
        "• Time-to-Decision (TTD)      : tick #{}",
        latency_tracker.decision_tick.unwrap_or(0)
    );
    println!("------------------------------------------------------------");
    println!("Energy: not reported. This host demo has no cycle count or current measurement;");
    println!(
        "on a target, use cycles x active power / clock (EnergyEstimator::cpu_active_nanojoules)."
    );
    println!("============================================================");
    println!("✅ Benchmark completed with ZERO dynamic heap allocations (#![no_std]).");
}
